package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen0Test {

    @Test
    public void testRandom_CountZero() {
        String result = RandomStringUtils.random(0, 0, 0, true, true, null, new Random());
        assertEquals("", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_CountNegative() {
        RandomStringUtils.random(-1, 0, 0, true, true, null, new Random());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_EmptyCharsArray() {
        RandomStringUtils.random(5, 0, 0, true, true, new char[0], new Random());
    }

    @Test
    public void testRandom_WithCharsArray() {
        char[] chars = {'a', 'b', 'c'};
        // start=0, end=3 covers indices 0, 1, 2
        String result = RandomStringUtils.random(5, 0, 3, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }

    @Test
    public void testRandom_DefaultLogic_NoLettersNoNumbers() {
        // If start=0, end=0, chars=null, letters=false, numbers=false -> end = Integer.MAX_VALUE
        // This is hard to test fully due to MAX_VALUE, but we check it doesn't crash
        String result = RandomStringUtils.random(2, 0, 0, false, false, null, new Random());
        assertEquals(2, result.length());
    }

    @Test
    public void testRandom_DefaultLogic_LettersOrNumbers() {
        // If start=0, end=0, chars=null, letters=true -> end = 'z' + 1, start = ' '
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_WithSurrogates_HighSurrogate() {
        // High surrogate range: 55296 to 56191
        char[] chars = {(char) 55296}; 
        // We need to force the logic where it hits the high surrogate branch
        // Since the code uses random.nextInt(gap) + start, we set gap=1, start=0
        String result = RandomStringUtils.random(1, 0, 1, false, false, chars, new Random());
        // The logic for high surrogate: buffer[count] = low, buffer[count-1] = high. 
        // Because count becomes 0 immediately, it hits the 'if(count==0) count++' safety or similar.
        // Actually, in the code: if(count==0) count++, it prevents buffer overflow.
        // Let's test a larger count to trigger the buffer insertion.
        char[] chars2 = {(char) 55296, 'a'};
        String result2 = RandomStringUtils.random(5, 0, 2, false, false, chars2, new Random());
        // The length might be more than 5 due to surrogate pair insertion
        assertTrue(result2.length() >= 1);
    }

    @Test
    public void testRandom_WithSurrogates_LowSurrogate() {
        // Low surrogate range: 56320 to 57343
        char[] chars = {(char) 56320, 'a'};
        String result = RandomStringUtils.random(5, 0, 2, false, false, chars, new Random());
        assertTrue(result.length() >= 1);
    }

    @Test
    public void testRandom_WithSurrogates_PrivateHighSurrogate() {
        // Private high surrogate: 56192 to 56319 (should be skipped)
        char[] chars = {(char) 56200, 'a'};
        // We want to see if it skips the private surrogate and eventually produces 'a'
        String result = RandomStringUtils.random(2, 0, 2, false, false, chars, new Random());
        // If it skips, it will keep looping until it picks 'a'
        assertTrue(result.length() >= 1);
    }

    @Test
    public void testRandom_FilteringLogic() {
        // Test that letters=true, numbers=false only returns letters
        char[] chars = {'a', '1', 'b', '2'};
        String result = RandomStringUtils.random(10, 0, 4, true, false, chars, new Random());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isLetter(c));
        }

        // Test that letters=false, numbers=true only returns numbers
        result = RandomStringUtils.random(10, 0, 4, false, true, chars, new Random());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isDigit(c));
        }

        // Test that letters=false, numbers=false returns only non-letter/non-digit
        char[] chars2 = {'!', 'a', '1'};
        result = RandomStringUtils.random(10, 0, 3, false, false, chars2, new Random());
        for (char c : result.toCharArray()) {
            assertFalse(Character.isLetter(c));
            assertFalse(Character.isDigit(c));
        }
    }

    @Test
    public void testRandom_WithChars_StartEnd() {
        char[] chars = {'a', 'b', 'c', 'd', 'e'};
        // start=1, end=4 -> indices 1, 2, 3 ('b', 'c', 'd')
        String result = RandomStringUtils.random(5, 1, 4, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'b' || c == 'c' || c == 'd');
        }
    }
}
